-- composition of rule kernels BloomFilter x PropagateConst (sqlite), template union
SELECT count(*) FROM (SELECT 1 AS k FROM (WITH cte1 AS (SELECT '{"k": -1, "a": [1, 2, 3]}' AS c0) SELECT CAST(5e-324 AS REAL) AS c0, 2 AS c1, (SELECT MIN (a2.c3) FROM (t4 AS a2 JOIN t4 AS a3 ON (a2.c0 = a3.c0)) WHERE (a2.c0 = 10)) AS c2 FROM t0 AS a1 UNION SELECT CAST(0.5 AS REAL) AS c0, 16 AS c1, CAST(0.0 AS NUMERIC) AS c2) AS ka UNION ALL SELECT 2 AS k FROM (SELECT '{"k": 2, "a": [0]}' AS c0 FROM tp AS a1 WHERE ((a1.c1, CASE WHEN FALSE THEN TRUE ELSE (CAST(1 AS INTEGER) IN (SELECT CAST(100 AS INTEGER) AS c0)) END) <> (a1.c1, TRUE)) GROUP BY a1.c0, a1.c1) AS kb) AS u;
